class Solution {
  public long minArraySum(int[] nums) {
    int MAX = 100_001;
    boolean[] present = new boolean[MAX];
    for (int v : nums) present[v] = true;
    int[] best = new int[MAX];
    for (int d = 1; d < MAX; d++) {
      if (!present[d]) continue;
      for (int m = d; m < MAX; m += d) if (best[m] == 0) best[m] = d;
    }
    long sum = 0;
    for (int v : nums) sum += best[v];
    return sum;
  }
}
